<script setup>
import {ref,computed} from 'vue';import {Plus,BookOpen} from '@lucide/vue';import {request} from '../lib/api';import {state,refreshReference,notify} from '../lib/store';
const sourceForm=ref({name:'',kind:'compendium',reference:''}),classForm=ref({name:'',sourceId:''}),sourceBusy=ref(false),classBusy=ref(false),sourceError=ref(''),classError=ref('');
const ownSources=computed(()=>state.sources.filter(s=>s.ownerUserId===state.user.id));
async function addSource(){sourceBusy.value=true;sourceError.value='';try{const r=await request('/sources',{method:'POST',body:{...sourceForm.value,reference:sourceForm.value.reference||null}});await refreshReference();classForm.value.sourceId=r.data.id;sourceForm.value={name:'',kind:'compendium',reference:''};notify('Coleção criada. Agora você pode adicionar suas classes.');}catch(e){sourceError.value=e.message;}finally{sourceBusy.value=false;}}
async function addClass(){classBusy.value=true;classError.value='';try{await request('/classes',{method:'POST',body:{name:classForm.value.name,...(classForm.value.sourceId?{sourceId:Number(classForm.value.sourceId)}:{})}});await refreshReference();classForm.value.name='';notify('Classe adicionada. Abra uma magia no catálogo para vinculá-la a essa classe.');}catch(e){classError.value=e.message;}finally{classBusy.value=false;}}
</script>
<template><div class="page-heading"><div><p class="breadcrumb">Expanda seu repertório</p><h1>Classes e compêndios</h1><p class="page-description">Organize suas coleções e acrescente classes ao livro de magias.</p></div></div><div class="management-grid"><section class="form-section"><h2>Nova coleção</h2><p class="muted">Compêndios e homebrews criados aqui ficam na sua conta.</p><form @submit.prevent="addSource"><label>Nome da coleção<input v-model="sourceForm.name" required maxlength="200" placeholder="Ex.: Compêndio da nossa mesa"/></label><label>Tipo<select aria-label="Tipo" v-model="sourceForm.kind"><option value="compendium">Compêndio</option><option value="homebrew">Homebrew</option></select></label><label>Referência <span class="optional">(opcional)</span><input v-model="sourceForm.reference" maxlength="2000" placeholder="Livro, autor ou endereço"/></label><p v-if="sourceError" class="alert" role="alert">{{sourceError}}</p><button class="button" :disabled="sourceBusy"><Plus :size="16"/>{{sourceBusy?'Criando…':'Criar coleção'}}</button></form></section><section class="form-section"><h2>Nova classe</h2><p class="muted">Depois, abra os detalhes de uma magia para acrescentá-la à lista da classe.</p><form @submit.prevent="addClass"><label>Nome da classe<input v-model="classForm.name" required maxlength="200" placeholder="Ex.: Tecnomante"/></label><label>Coleção<select aria-label="Coleção" v-model="classForm.sourceId"><option value="">Meus homebrews (padrão)</option><option v-for="s in ownSources" :key="s.id" :value="s.id">{{s.name}}</option></select></label><p v-if="classError" class="alert" role="alert">{{classError}}</p><button class="button" :disabled="classBusy"><Plus :size="16"/>{{classBusy?'Criando…':'Adicionar classe'}}</button></form></section></div><section class="classes-section"><div class="section-heading"><h2>Classes disponíveis</h2><span class="muted">{{state.classes.length}} classes</span></div><div class="classes-table"><div v-for="c in state.classes" :key="c.id" class="class-row"><BookOpen :size="18"/><strong>{{c.name}}</strong><span>{{c.source}}</span><span class="tag">{{c.sourceKind==='book'?'Livro':c.sourceKind==='compendium'?'Compêndio':'Homebrew'}}</span></div></div></section></template>
